using System.Collections;
using Unity.VisualScripting;
using UnityEngine;

public class Boss : EnemyBehaviorBase 
{
    KeyAndLock keyAndLock;
    new Animation animation;
    [SerializeField] private GameManager gameManager;
    public Transform XRRigCamera;
    public Transform rotatingBase;
    public Transform rotatingEye;
    private Quaternion targetBaseRotation;
    private Quaternion targetEyeRotation;
    [SerializeField] private float rotationSpeed = 2f;
    [SerializeField] private GameObject Bossdeathsphere;

    public GameObject bossEye;
    private Animation bossEyeAnimation;

    [SerializeField] private float minAttackInterval = 3f;
    [SerializeField] private float maxAttackInterval = 6f;
    [SerializeField] private GameObject laserPrefab;
    [SerializeField] private Transform laserSpawnPoint;
    [SerializeField] private ParticleSystem ParticlesSlam;
    [SerializeField] private ParticleSystem ParticlesSlam2;
    [SerializeField] private AudioSource BattleMusic;
    [SerializeField] private AudioSource Ambience;
    private EnemyHealth enemyHealth;

    private float attackTimer;
    private bool isAttacking = false;
    private bool LaserAttacking = false;
    public bool AttackingBossPossible = false;
    public bool BossStartingup = false;
    public bool BossWaveActive = false;
    public bool BossbattlestartAudio = false;
    public bool BossbattleAudioON = false;
    public bool Bossdead = false;
    private enum AttackType { Slam, Laser }

    public bool BossIsAwake;
    public bool BossIsIdle;

    protected override void Start()
    {
        animation = GetComponent<Animation>();
        bossEyeAnimation = bossEye.GetComponent<Animation>();
        enemyHealth = GetComponent<EnemyHealth>();

        BossIsAwake = false;
        BossIsIdle = false;
        BossStartingup = false;
        BossWaveActive = false;
        BossbattlestartAudio = false;        
        BossbattleAudioON = false;
        Bossdead = false;
        attackTimer = Random.Range(minAttackInterval, maxAttackInterval);
        Bossdeathsphere.SetActive(false);

        if (enemyHealth == null)
        {
            Debug.LogError("EnemyHealth component not found on Boss object.");
        }
    }

    public override void idle()
    {
        BossIsIdle = true;
    }

    public override void attack()
    {
        AttackType attackType = (Random.value < 0.5f) ? AttackType.Laser : AttackType.Slam;
        StartCoroutine(PerformAttack(attackType));
    }

    public override void wondering()
    {
        currentState= BotBase.Attack;
    }

    public override void Startup()
    {
        Debug.Log("boss startup word aangeroepen");
        if (BossStartingup)
        {
            animation.Play("Boss_WakesUp");
            StartCoroutine(WaitforStartup());
        }
    }

    public void BossAwake()
    {
        BossIsAwake = true;
        ChangeState(BotBase.Idle);
    }

    public override void DoChase()
    {
        ChangeState(BotBase.Attack);
    }

    protected override void Update()
    {
        if(BossbattlestartAudio)
        {
            if(!BossbattleAudioON)
            {
                BattleMusic.Play();
                BattleMusic.loop = true;
                BossbattleAudioON = true;
            }
        }

        if (!LaserAttacking && BossWaveActive && !Bossdead)
        {
            bossEyeAnimation.Play("BossEye_Active");
        }

        if (!BossIsIdle || Bossdead) return;

        animation.Play("Boss_Idle");

        if (XRRigCamera != null && rotatingBase != null)
        {
            Vector3 targetPosition = XRRigCamera.position;
            targetPosition.y = rotatingBase.position.y;

            Vector3 direction = targetPosition - rotatingBase.position;

            if (direction.sqrMagnitude > 0.001f)
            {
                Quaternion lookRotation = Quaternion.LookRotation(direction);
                Vector3 euler = lookRotation.eulerAngles;
                targetBaseRotation = Quaternion.Euler(-90f, euler.y + 180f, 0f);
            }

            if (!isAttacking)
            {
                rotatingBase.rotation = Quaternion.Slerp(rotatingBase.rotation, targetBaseRotation, Time.deltaTime * rotationSpeed);
            }

            if (rotatingEye != null)
            {
                Quaternion eyeLook = Quaternion.LookRotation(XRRigCamera.position - rotatingEye.position);
                targetEyeRotation = eyeLook;

                if (!isAttacking)
                {
                    rotatingEye.rotation = Quaternion.Slerp(rotatingEye.rotation, targetEyeRotation, Time.deltaTime * rotationSpeed);
                }
            }
        }

        if(BossWaveActive)
        {
            attackTimer -= Time.deltaTime;
        }

        if (attackTimer > 0f) return;

        BossIsIdle = false;
        attack();
    }

    private void FireLaser()
    {
        if (laserPrefab != null && laserSpawnPoint != null)
        {
            GameObject laserInstance = Instantiate(laserPrefab, laserSpawnPoint.position, laserSpawnPoint.rotation);
        }
    }

    public void BossDead()
    {
        Debug.Log("Boss is dead!1");

        if (!Bossdead)
        {
            Bossdeathsphere.SetActive(true);
            Debug.Log("Boss is dead!2");
            Bossdead = true;
            BossIsAwake = false;
            BossIsIdle = false;
            BossStartingup = false;
            BossbattlestartAudio = false;
            BossbattleAudioON = false;

            AudioManager.Instance.audioClips[10].Stop();
            AudioManager.Instance.audioClips[8].Stop();

            if (BattleMusic != null && BattleMusic.isPlaying)
            {
                BattleMusic.Stop();
                Ambience.Play();
            }

            bossEyeAnimation.Play("BossEye_Destruct");
            animation.Play("Boss_destruct");
            AudioManager.Instance.audioClips[11].Play();
            gameManager.Bossisdead();
            ShowObjective.instance.ShowObjectiveCanvas(7);
        }
    }

    private IEnumerator PerformAttack(AttackType attackType)
    {
        isAttacking = true;

        switch (attackType)
        {
            case AttackType.Slam:
                animation.Play("Boss_Slam");
                AudioManager.Instance.audioClips[8].Play();
                yield return new WaitForSeconds(3.5f);
                ParticlesSlam.Play();
                ParticlesSlam2.Play();
                AttackingBossPossible = true;
                yield return new WaitForSeconds(5.3f);
                break;

            case AttackType.Laser:
                if (bossEyeAnimation != null)
                {
                    bossEyeAnimation.Play("BossEye_ChargeforLaser");
                    AudioManager.Instance.audioClips[10].Play();
                    LaserAttacking = true;
                }
                yield return new WaitForSeconds(5.2f);

                FireLaser();

                break;
        }

        if(Bossdead)
        {
            BossIsIdle = false;
            BossIsAwake = false;
            BossStartingup = false;
            BossWaveActive = false;
            BossbattlestartAudio = false;
            BossbattleAudioON = false;
        }
        else
        {
            attackTimer = Random.Range(minAttackInterval, maxAttackInterval);
            isAttacking = false;
            LaserAttacking = false;
            AttackingBossPossible = false;
            BossIsIdle = true;
        }
    }

    private IEnumerator WaitforStartup()
    {
        Debug.Log("boss waitfor startup startup word aangeroepen");
        BossWaveActive = true;
        var enemies = new System.Collections.Generic.List<GameObject>();
        enemies.AddRange(GameObject.FindGameObjectsWithTag("Light"));
        enemies.AddRange(GameObject.FindGameObjectsWithTag("Medium"));
        enemies.AddRange(GameObject.FindGameObjectsWithTag("Heavy"));
        Ambience.Stop();
        foreach (GameObject enemy in enemies)
        {
            if (enemy != this.gameObject)
            {
                enemy.SetActive(false);
            }
        }
        AudioManager.Instance.audioClips[9].Play();
        yield return new WaitForSeconds(9.8f);
        BossbattlestartAudio = true;
        idle();
    }
}

public void OnSelectEntered(SelectEnterEventArgs args)
{
    grabbed = true;
    rb.isKinematic = true;
}

public void OnSelectExited(SelectExitEventArgs args)
{
    grabbed = false;
    rb.isKinematic = false;
}

void Update()
{
    switch(state)
    {
        case Idle:
            LookForPlayer();
            break;

        case Chase:
            MoveTowardPlayer();
            break;

        case Attack:
            TryShoot();
            break;
    }
}

void Shoot()
{
    Ray ray = new Ray(transform.position, transform.forward);

    if (Physics.Raycast(ray, out var hit, 50f))
    {
        Debug.Log($"Hit {hit.collider.name}");
    }
}

public class StepGuide : MonoBehaviour
{
    public List<TrainingStep> steps;
    private int currentStep = 0;

    void CheckStepCompletion()
    {
        if (steps[currentStep].IsCompleted())
        {
            currentStep++;
            ShowNextInstruction();
        }
    }
}

bool ValidateHandPose(HandPose required)
{
    float similarity = Vector3.Dot(
        currentPose.palmNormal,
        required.palmNormal
    );

    return similarity > 0.95f;
}

void OnTrackedImagesChanged(ARTrackedImagesChangedEventArgs args)
{
    foreach (var trackedImage in args.added)
    {
        string artworkId = trackedImage.referenceImage.name;
        SpawnARContent(artworkId, trackedImage.transform);
    }
}

void HandleTouchInput()
{
    if (Input.touchCount == 2)
    {
        Touch t1 = Input.GetTouch(0);
        Touch t2 = Input.GetTouch(1);

        float pinchDist = Vector2.Distance(t1.position, t2.position);
        float scale = pinchDist / initialPinchDist;

        model.localScale = initialScale * scale;
    }
}
